package factory

import (
	"context"
	"encoding/json"
	"html"
	"reflect"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/project"
)

type mistake947 struct {
	Says   string   `json:"says"`
	Bugs   []string `json:"bugs,omitempty"`
	Reason string   `json:"reason,omitempty"`
}

func withMistakes947(t *testing.T, p *formalize.Proposal, rows []mistake947) *formalize.Proposal {
	t.Helper()
	wire := reader603Object(t, p)
	wire["mistakes"] = rows
	var copy formalize.Proposal
	if err := json.Unmarshal(reader603JSON(t, wire), &copy); err != nil {
		t.Fatal(err)
	}
	return &copy
}

func readMistakes947(t *testing.T, p *formalize.Proposal) []mistake947 {
	t.Helper()
	var wire struct {
		Mistakes []mistake947 `json:"mistakes"`
	}
	if err := json.Unmarshal(reader603JSON(t, p), &wire); err != nil {
		t.Fatal(err)
	}
	return wire.Mistakes
}

func visibleMistakes947(t *testing.T, body string, rows []mistake947) {
	t.Helper()
	// The encoded marker alone is not a human-visible account of coverage.
	visible := reader603Visible(body)
	literal := html.UnescapeString(visible)
	last := -1
	for _, row := range rows {
		at := strings.Index(literal, row.Says)
		if at < 0 {
			t.Errorf("visible proposal lacks the issue's mistake %q", row.Says)
			continue
		}
		if at <= last {
			t.Error("mistake record changed the issue's order")
		}
		last = at
		// These fixtures use one-line entries: disposition and wording belong
		// together, not in a separate list of bugs that might imply coverage.
		start := strings.LastIndex(literal[:at], "\n") + 1
		end := strings.Index(literal[at:], "\n")
		line := literal[start:]
		if end >= 0 {
			line = literal[start : at+end]
		}
		for _, bug := range row.Bugs {
			if !strings.Contains(line, bug) {
				t.Errorf("mistake %q is not paired with bug %q", row.Says, bug)
			}
		}
		if row.Reason != "" && !strings.Contains(line, row.Reason) {
			t.Errorf("mistake %q is not paired with its omission reason", row.Says)
		}
	}
	if strings.Contains(visible, "<script>") || strings.Contains(visible, "<!-- hidden -->") || strings.Contains(visible, "[follow](https://example.invalid)") {
		t.Error("mistake text became active markup instead of literal text")
	}
}

func TestMistakeProposalComments947(t *testing.T) {
	rows := []mistake947{
		{Says: "1. Accepting after the capacity check | too late.", Bugs: []string{"PutWhenFull"}},
		{Says: "2. Losing <script> or [follow](https://example.invalid) during handoff.", Reason: "No handoff action is modeled <!-- hidden -->; review this omission."},
	}
	base := bufferProposal(t)
	checkedBufferReader(t, base)
	p := withMistakes947(t, base, rows)
	current := &formalize.Current{ModuleText: base.ModuleText, Lock: project.Lock{Bounds: base.Bounds, Statements: base.Statements}}
	amend := *p
	amend.Target = &formalize.Target{Dir: "examples/buffer", Previous: "#1", Amends: base.Hash, Manifest: base.Manifest()}
	forks := []formalize.Fork{{ID: "F1", Question: "Which handoff?", Options: []formalize.Option{
		{ID: "A", Says: "Keep it in the buffer.", Preview: &formalize.Preview{Fork: "F1", Option: "A", Model: p}},
		{ID: "B", Says: "Send it immediately.", Preview: &formalize.Preview{Fork: "F1", Option: "B", Model: base}},
	}}}
	question := &formalize.Proposal{Draft: formalize.Draft{Forks: forks}}
	for _, compact := range []bool{false, true} {
		m := Marker{Kind: KindProposal, Proposal: p}
		am := Marker{Kind: KindProposal, Proposal: &amend}
		fm := Marker{Kind: KindForks, Proposal: question, Forks: forks}
		evidence := ""
		if compact {
			m.ProposalRef, am.ProposalRef, fm.ProposalRef = review911Reference, review911Reference, review911Reference
			evidence = review911Evidence
		}
		visibleMistakes947(t, proposalCommentWithEvidence(p, nil, m, evidence), rows)
		visibleMistakes947(t, amendmentCommentWithEvidence(&amend, nil, formalize.Diff(current, &amend), am, evidence), rows)
		body := forksComment(forks, fm)
		if compact {
			body = compactForksComment(forks, fm, evidence)
		}
		visibleMistakes947(t, body, rows)
		visible := html.UnescapeString(reader603Visible(body))
		if a, b, record := strings.Index(visible, "Keep it in the buffer."), strings.Index(visible, "Send it immediately."), strings.Index(visible, rows[0].Says); record < a || record >= b {
			t.Error("option A's mistake record is not shown with option A")
		}
	}
	// Coverage is indispensable decision text: the caller must refuse an
	// oversized comment, not offer a ratification of clipped coverage.
	long := []mistake947{{Says: strings.Repeat("Listed mistake. ", maxComment/8), Reason: "Explicit omission at the end of the complete record."}}
	large := withMistakes947(t, base, long)
	for _, compact := range []bool{false, true} {
		m := Marker{Kind: KindProposal, Proposal: large}
		evidence := ""
		if compact {
			m.ProposalRef, evidence = review911Reference, review911Evidence
		}
		body := proposalCommentWithEvidence(large, nil, m, evidence)
		if completeComment(body, m) || !strings.Contains(reader603Visible(body), long[0].Says) || !strings.Contains(reader603Visible(body), long[0].Reason) {
			t.Error("oversized mistake coverage was omitted or clipped to fit")
		}
	}
}

func TestMistakeSavedProposal947(t *testing.T) {
	rows := []mistake947{{Says: "A persisted mistake, in the issue's words.", Reason: "No bug is planted for this case; assess the omission."}}
	base := saved790Result(t, false)
	p := withMistakes947(t, base.Proposal, rows)
	m := Marker{Kind: KindProposal, Proposal: p}
	decoded, ok := DecodeMarker(m.encode())
	if !ok || !reflect.DeepEqual(readMistakes947(t, decoded.Proposal), rows) {
		t.Error("inline marker lost the complete mistake record")
	}
	for _, invalid := range []bool{false, true} {
		// Inject into the persisted JSON independently of Draft's Go fields,
		// then recompute the payload digest just as immutable storage does.
		wire := reader603Object(t, base)
		want := rows
		if invalid {
			want = []mistake947{{Says: rows[0].Says}}
		}
		wire["proposal"].(map[string]any)["mistakes"] = want
		payload := reader603JSON(t, wire)
		commit := strings.Repeat("a", 40)
		ref := DraftReference{Version: 1, Repository: "o/r", Issue: 947, Step: "draft-issue", Commit: commit, SHA256: saved790Digest(payload), ProposalHash: base.Proposal.Hash}
		refJSON, err := json.Marshal(ref)
		if err != nil {
			t.Fatal(err)
		}
		marker := Marker{Kind: KindProposal, ProposalRef: refJSON}
		hydrated, result, err := marker.ResolveDraft(t.Context(), "o/r", 947,
			func(_ context.Context, issue int, step string) (RunState, string, error) {
				if issue != 947 || step != "draft-issue" {
					t.Fatalf("wrong saved run: %d %s", issue, step)
				}
				return RunDone, commit, nil
			}, func(_ context.Context, gotCommit, file string) ([]byte, error) {
				if gotCommit != commit || file != "result.json" {
					t.Fatalf("unexpected saved source: %s %s", gotCommit, file)
				}
				return payload, nil
			})
		if invalid {
			if err == nil || !strings.Contains(err.Error(), rows[0].Says) {
				t.Errorf("saved proposal with no disposition was not refused by name: %v", err)
			}
			if err != nil && (hydrated.Proposal != nil || result != nil) {
				t.Error("refused saved evidence supplied a usable proposal")
			}
			continue
		}
		if err != nil || result == nil {
			t.Fatalf("valid saved coverage refused: %v", err)
		}
		for _, proposal := range []*formalize.Proposal{hydrated.Proposal, result.Proposal} {
			if !reflect.DeepEqual(readMistakes947(t, proposal), rows) {
				t.Error("saved reference lost exact mistake evidence")
			}
			if proposal.Hash != base.Proposal.Hash {
				t.Error("saved coverage changed statement ratification identity")
			}
		}
	}
}

