package formalize_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/formalize"
	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/synth"
)

// The record is an ordered transcription, not an issue parser or a claim
// that a named bug faithfully models a mistake. Those remain reviewable.
type mistake947 struct {
	Says   string   `json:"says"`
	Bugs   []string `json:"bugs,omitempty"`
	Reason string   `json:"reason,omitempty"`
}

func mistakes947(t *testing.T, p *formalize.Proposal) []mistake947 {
	t.Helper()
	var wire struct {
		Mistakes []mistake947 `json:"mistakes"`
	}
	if err := json.Unmarshal(reader603JSON(t, p), &wire); err != nil {
		t.Fatal(err)
	}
	return wire.Mistakes
}

func writeMistakes947(t *testing.T, ws string, rows []mistake947) {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(ws, "proposal.json"))
	if err != nil {
		t.Fatal(err)
	}
	var d map[string]any
	if err := json.Unmarshal(b, &d); err != nil {
		t.Fatal(err)
	}
	if rows == nil {
		delete(d, "mistakes")
	} else {
		d["mistakes"] = rows
	}
	reader603Write(t, filepath.Join(ws, "proposal.json"), string(reader603JSON(t, d)))
}

func bufferMistakes947(t *testing.T, rows []mistake947) string {
	t.Helper()
	ws := t.TempDir()
	for _, name := range []string{"proposal.json", "BoundedBuffer.tla"} {
		b, err := os.ReadFile(filepath.Join("testdata", "buffer", name))
		if err != nil {
			t.Fatal(err)
		}
		reader603Write(t, filepath.Join(ws, name), string(b))
	}
	reader603Write(t, filepath.Join(ws, "view.json"), `{"version":1,"state":[{"id":"all","when":true,"label":"Buffer"}],"step":[{"id":"all","when":true,"label":"Update buffer"}]}`)
	writeMistakes947(t, ws, rows)
	return ws
}

func TestMistakeDraftingInstructions947(t *testing.T) {
	base := formalize.Request{Repo: "o/r", Issue: 8, Title: "Bounded buffer", Body: "## Mistakes worth guarding against\n\n1. Accepting another item when the buffer is already full.\n2. Dropping an item when handing it to the shipper."}
	p, err := formalize.Read(bufferMistakes947(t, nil))
	if err != nil {
		t.Fatal(err)
	}
	current := &formalize.Current{Dir: "example/buffer", Manifest: p.Manifest(), ModuleText: p.ModuleText, Lock: project.Lock{Bounds: p.Bounds, Statements: p.Statements}}
	for _, variant := range []string{"new", "existing", "amendment", "revision"} {
		req := base
		switch variant {
		case "existing":
			req.Existing = &formalize.Existing{Paths: []string{"src/buffer.ts"}}
		case "amendment":
			req.Current = current
		case "revision":
			req.Previous = p
		}
		prompt := formalize.Prompt(req, 4)
		for _, want := range []string{"mistakes", "each mistake", "step", "moment", "issue's words", "\"bugs\"", "\"reason\""} {
			if !strings.Contains(prompt, want) {
				t.Errorf("%s drafting guidance lacks %q", variant, want)
			}
		}
		if strings.Contains(prompt, "Add known bugs for the mistakes that matter most") {
			t.Errorf("%s still directs the agent to select only the most important listed mistakes", variant)
		}
	}
}

func TestMistakeRecordValidation947(t *testing.T) {
	for _, tc := range []struct {
		name string
		row  mistake947
		ref  string
	}{
		{"no disposition", mistake947{Says: "Accepting after the buffer fills."}, ""},
		{"blank reason", mistake947{Says: "Losing the shipper's item.", Reason: " \n\t"}, ""},
		{"both dispositions", mistake947{Says: "Contradictory coverage.", Bugs: []string{"PutWhenFull"}, Reason: "No bug."}, ""},
		{"blank text", mistake947{Says: " \n", Bugs: []string{"PutWhenFull"}}, ""},
		{"undefined bug", mistake947{Says: "Invented reference.", Bugs: []string{"NotDefined947"}}, "NotDefined947"},
		{"invariant reference", mistake947{Says: "An invariant is not a planted bug.", Bugs: []string{"WithinCap"}}, "WithinCap"},
		{"action reference", mistake947{Says: "A normal action is not a declared bug.", Bugs: []string{"Put"}}, "Put"},
		{"blank reference", mistake947{Says: "An empty name supplies no bug.", Bugs: []string{" "}}, ""},
		{"repeated reference", mistake947{Says: "The same reference appears twice.", Bugs: []string{"PutWhenFull", "PutWhenFull"}}, "PutWhenFull"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			// The bad entry follows a valid one, so diagnostics must identify it.
			rows := []mistake947{{Says: "Already covered.", Bugs: []string{"PutWhenFull"}}, tc.row}
			_, err := formalize.Read(bufferMistakes947(t, rows))
			if err == nil {
				t.Fatal("Read accepted an invalid mistake record")
			}
			if !strings.Contains(strings.ToLower(err.Error()), "mistake") {
				t.Errorf("diagnostic does not identify the mistake record: %v", err)
			}
			if strings.TrimSpace(tc.row.Says) != "" && !strings.Contains(err.Error(), tc.row.Says) {
				t.Errorf("diagnostic does not identify the offending mistake %q: %v", tc.row.Says, err)
			}
			if tc.ref != "" && !strings.Contains(err.Error(), tc.ref) {
				t.Errorf("diagnostic omits bad reference %q: %v", tc.ref, err)
			}
		})
	}
}

func TestMistakeRecordRoundTrip947(t *testing.T) {
	rows := []mistake947{
		{Says: "1. Accepting at the full-buffer step | before checking `Cap`.", Bugs: []string{"PutWhenFull", "PutAgain947"}},
		{Says: "2. Losing the item\n   during the shipper handoff.", Reason: "The model has no shipper; this is an explicit omission for review."},
		{Says: "3. Appending after a retry sees a full buffer.", Bugs: []string{"PutWhenFull"}},
	}
	ws := bufferMistakes947(t, rows)
	b, err := os.ReadFile(filepath.Join(ws, "BoundedBuffer.tla"))
	if err != nil {
		t.Fatal(err)
	}
	reader603Write(t, filepath.Join(ws, "BoundedBuffer.tla"), strings.Replace(string(b), "Spec ==", "PutAgain947 == PutWhenFull\n\nSpec ==", 1))
	b, err = os.ReadFile(filepath.Join(ws, "proposal.json"))
	if err != nil {
		t.Fatal(err)
	}
	var d map[string]any
	if err := json.Unmarshal(b, &d); err != nil {
		t.Fatal(err)
	}
	d["statements"] = append(d["statements"].([]any), map[string]any{"name": "PutAgain947", "kind": "bug", "says": "An unchecked append on retry.", "expect": "WithinCap", "code_behavior": "hypothetical"})
	reader603Write(t, filepath.Join(ws, "proposal.json"), string(reader603JSON(t, d)))
	p, err := formalize.Read(ws)
	if err != nil {
		t.Fatal(err)
	}
	var round formalize.Proposal
	if err := json.Unmarshal(reader603JSON(t, p), &round); err != nil {
		t.Fatal(err)
	}
	if got := mistakes947(t, &round); !reflect.DeepEqual(got, rows) {
		t.Errorf("proposal lost exact ordered mistake evidence: got %#v, want %#v", got, rows)
	}
	if p.Hash != project.ProposalHash(p.Bounds, p.Statements) {
		t.Error("explanatory mistake metadata changed the statement hash contract")
	}
	writeMistakes947(t, ws, nil)
	legacy, err := formalize.Read(ws)
	if err != nil || legacy.Hash != p.Hash || !reflect.DeepEqual(legacy.Statements, p.Statements) {
		t.Fatalf("removing explanatory metadata altered statements: %v", err)
	}
	if _, exists := reader603Object(t, legacy)["mistakes"]; exists {
		t.Error("legacy proposals gained a serialized mistakes field")
	}
	writeMistakes947(t, ws, []mistake947{})
	if _, err := formalize.Read(ws); err != nil {
		t.Fatalf("an issue without listed mistakes cannot keep an empty record: %v", err)
	}
}

func TestMistakeCheckAndFinalValidation947(t *testing.T) {
	tc, _ := reader603Tools(t) // Existing fake checks TLC flags, staged sources and output.
	bad := []mistake947{{Says: "Advancing at the wrong moment."}}
	good := []mistake947{{Says: bad[0].Says, Reason: "This candidate omits the fault; a person must assess that omission."}}
	ws := t.TempDir()
	reader603Workspace(t, ws)
	writeMistakes947(t, ws, bad)
	if _, _, err := formalize.Check(t.Context(), ws, tc); err == nil || !strings.Contains(err.Error(), bad[0].Says) {
		t.Errorf("draft check failed to explain missing coverage: %v", err)
	}
	writeMistakes947(t, ws, good)
	p, _ := reader603Checked(t, ws, tc)
	if !reflect.DeepEqual(mistakes947(t, p), good) {
		t.Error("repair lost its explicit omission reason")
	}
	for _, damage := range []bool{true, false} {
		a := reader603Agent{run: func(ctx context.Context, j synth.Job) (synth.Usage, error) {
			reader603Workspace(t, j.Workspace)
			writeMistakes947(t, j.Workspace, good)
			checked, report := reader603Checked(t, j.Workspace, tc)
			// A previous passing check cannot authorize a subsequently broken record.
			reader603Write(t, filepath.Join(j.Workspace, "formalization.json"), string(reader603JSON(t, formalize.Result{Proposal: checked, Report: report})))
			if damage {
				writeMistakes947(t, j.Workspace, bad)
			}
			return synth.Usage{}, nil
		}}
		out := t.TempDir()
		res, err := (formalize.Formalizer{Backend: a, Toolchain: tc, CheckRuns: 4}).Formalize(t.Context(), formalize.Request{Repo: "o/r", Issue: 947, Title: "Record mistakes"}, out)
		if err != nil || res == nil {
			t.Fatalf("formalizer: %v", err)
		}
		if damage {
			if !strings.Contains(res.Problem, bad[0].Says) {
				t.Errorf("independent final check accepted damaged coverage: problem=%q", res.Problem)
			}
			continue
		}
		if res.Problem != "" || !reflect.DeepEqual(mistakes947(t, res.Proposal), good) {
			t.Fatalf("repaired final draft: %+v", res)
		}
		data, err := os.ReadFile(filepath.Join(out, "formalization.json"))
		if err != nil {
			t.Fatal(err)
		}
		var saved formalize.Result
		if err := json.Unmarshal(data, &saved); err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(mistakes947(t, saved.Proposal), good) {
			t.Fatal("saved formalization lost mistake evidence")
		}
		revision := reader603Agent{run: func(ctx context.Context, j synth.Job) (synth.Usage, error) {
			data, err := os.ReadFile(filepath.Join(j.Workspace, "previous", "proposal.json"))
			if err != nil {
				t.Fatal(err)
			}
			var previous formalize.Proposal
			if err := json.Unmarshal(data, &previous); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(mistakes947(t, &previous), good) {
				t.Error("revision did not receive the previous mistake record")
			}
			reader603Write(t, filepath.Join(j.Workspace, "proposal.json"), `{"unsupported":"Fixture stops after reading the previous draft."}`)
			return synth.Usage{}, nil
		}}
		_, err = (formalize.Formalizer{Backend: revision, Toolchain: tc}).Formalize(t.Context(), formalize.Request{Previous: res.Proposal}, t.TempDir())
		if err != nil {
			t.Fatal(err)
		}
	}
}

func TestMistakePreviewValidation947(t *testing.T) {
	tc, _ := reader603Tools(t)
	ws := t.TempDir()
	d := preview639Draft(t, 1, nil)
	row := mistake947{Says: "F1 option A omits an advance guard."}
	preview639Input(d, 0, 0)["model"].(map[string]any)["mistakes"] = []mistake947{row}
	preview639Input(d, 0, 1)["model"].(map[string]any)["mistakes"] = []mistake947{{Says: "F1 option B uses an invariant as a bug.", Bugs: []string{"Safe"}}}
	preview639Write(t, ws, d)
	_, _, err := formalize.Check(t.Context(), ws, tc)
	if err == nil {
		t.Fatal("option check accepted incomplete and non-bug mistake coverage")
	}
	for _, want := range []string{"F1", "option A", "option B", row.Says, "Safe"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("option repair feedback omits %q: %v", want, err)
		}
	}
	row.Reason = "The option explicitly leaves this fault unmodeled."
	for i := 0; i < 2; i++ {
		preview639Input(d, 0, i)["model"].(map[string]any)["mistakes"] = []mistake947{row}
	}
	preview639Write(t, ws, d)
	p := preview639Checked(t, ws, tc)
	for _, o := range p.Forks[0].Options {
		if !reflect.DeepEqual(mistakes947(t, o.Preview.Model), []mistake947{row}) {
			t.Errorf("option %s lost repaired evidence", o.ID)
		}
	}
	out := t.TempDir()
	if err := p.WritePreviews(out); err != nil {
		t.Fatal(err)
	}
	for _, option := range []string{"A", "B"} {
		data, err := os.ReadFile(filepath.Join(out, "previews", "F1", option, "preview.json"))
		if err != nil {
			t.Fatal(err)
		}
		var saved formalize.Preview
		if err := json.Unmarshal(data, &saved); err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(mistakes947(t, saved.Model), []mistake947{row}) {
			t.Errorf("exported option %s lost repaired evidence", option)
		}
	}
}
